	read.AllowChannelSharingToExternalUser = reconcile.KeepBool(cfg.AllowChannelSharingToExternalUser, read.AllowChannelSharingToExternalUser)
	read.AllowCreateChannel = reconcile.KeepStr(cfg.AllowCreateChannel, read.AllowCreateChannel)
